/* بيانات قسم taam: تُحمَّل عند أول فتح للقسم */
window.TAAM = {"k":[{"id":"tin","c":"fawakih","t":"التين","d":"أقسم الله به في أول سورة سُمّيت باسمه.","r":[95,1]},{"id":"zaytun","c":"fawakih","t":"الزيتون وزيته","d":"شجرة مباركة ذُكرت في مواضع، ومنها مثل النور في سورة النور.","r":[24,35]},{"id":"nakhl","c":"nakhl","t":"النخل والتمر والرطب","d":"أكثر الأشجار ذكراً في القرآن، ورُزقت مريم رطبه عند المخاض.","r":[19,25]},{"id":"inab","c":"fawakih","t":"العنب والأعناب","d":"يُذكر غالباً مقروناً بالنخل في سياق الامتنان.","r":[16,11]},{"id":"rumman","c":"fawakih","t":"الرمان","d":"ذُكر في آيات النبات، وفي فاكهة الجنتين.","r":[55,68]},{"id":"asal","c":"sharab","t":"العسل","d":"شراب يخرج من بطون النحل، فيه شفاء للناس، ومن أنهار الجنة.","r":[16,69]},{"id":"laban","c":"sharab","t":"اللبن","d":"يخرج خالصاً من بين فرث ودم، سائغاً للشاربين.","r":[16,66]},{"id":"maa","c":"sharab","t":"الماء","d":"منه جعل الله كل شيء حي، ويُذكّر القرآن بنعمة إنزاله عذباً.","r":[56,68]},{"id":"mann","c":"aqwat","t":"المنّ والسلوى","d":"رزق أنزله الله على بني إسرائيل في التيه بلا تعب.","r":[2,57]},{"id":"baql","c":"aqwat","t":"البقل والقثاء والفوم والعدس والبصل","d":"ما سأله بنو إسرائيل بدلاً من المن والسلوى.","r":[2,61]},{"id":"lahm","c":"aqwat","t":"اللحم الطري وصيد البحر","d":"سخّر الله البحر ليؤكل منه لحم طري، وأحلّ صيده وطعامه.","r":[16,14]},{"id":"anam","c":"aqwat","t":"بهيمة الأنعام","d":"الإبل والبقر والغنم والمعز، أحلّها الله ويُذكر اسمه عليها.","r":[6,142]},{"id":"ijl","c":"qasas","t":"العجل الحنيذ","d":"قدّمه إبراهيم عليه السلام لضيفه مشوياً.","r":[11,69]},{"id":"khubz","c":"qasas","t":"الخبز","d":"ورد في رؤيا صاحب السجن مع يوسف عليه السلام.","r":[12,36]},{"id":"yaqtin","c":"qasas","t":"اليقطين","d":"شجرة أنبتها الله على يونس عليه السلام بعد خروجه من بطن الحوت.","r":[37,146]},{"id":"sunbul","c":"qasas","t":"الحَبّ والسنابل","d":"تدبير يوسف عليه السلام للقمح في سني الرخاء والشدة.","r":[12,47]}],"cats":[["fawakih","الفواكه"],["nakhl","النخل"],["sharab","الأشربة"],["aqwat","الأقوات"],["qasas","في القصص"]],"ch":[{"id":"fawakih","t":"الفواكه والثمار","d":"يعرض القرآن الثمار آيةً من آيات الله ونعمةً على عباده: ماء واحد ينبت ثماراً مختلفة الألوان والطعوم، وأشجار يقسم الله بها، وجنات معروشات وغير معروشات؛ ويأمر عند ذلك بالنظر والشكر وأداء الحق يوم الحصاد.","ay":[{"t":"القسم بالتين والزيتون","r":[95,1,3],"n":"أقسم الله بشجرتين مباركتين وبمواطن الرسالات، وهذا القسم تشريف للمقسم به."},{"t":"ماء واحد وثمار شتى","r":[6,99],"n":"النخل والأعناب والزيتون والرمان من ماء واحد، ثم الأمر بالنظر إلى الثمر إذا أثمر وإلى ينعه: دعوة إلى التفكر في الطعام قبل أكله."},{"t":"كلوا من ثمره وآتوا حقه","r":[6,141],"n":"جمعت الإباحة والشكر والنهي عن الإسراف في آية واحدة."},{"t":"يُسقى بماء واحد ويُفضَّل بعضها على بعض في الأكل","r":[13,4],"n":"اختلاف طعوم الثمار مع اتحاد الماء والتربة آية لقوم يعقلون."},{"t":"شجرة طور سيناء","r":[23,19,20],"n":"الجنات من النخيل والأعناب، والشجرة التي تنبت بالدهن وصبغ للآكلين، وهي الزيتونة عند المفسرين."},{"t":"فبأي آلاء ربكما تكذبان","r":[55,10,13],"n":"الأرض وُضعت للأنام، فيها فاكهة والنخل ذات الأكمام والحب ذو العصف والريحان."}]},{"id":"nakhl","t":"النخل والتمر","d":"النخلة أكثر الأشجار ذكراً في القرآن؛ ذُكرت باسم النخل والنخيل والنخلة، وثمرها الرطب والتمر، وضرب بها المثل للكلمة الطيبة. وقد رزق الله مريم عليها السلام رطبها عند المخاض، وامتن على العباد بطلعها النضيد.","ay":[{"t":"رطب مريم","r":[19,23,26],"n":"هزّ الجذع مع ضعفها، فهو أخذ بالأسباب، والرزق من الله؛ ثم قال: «فكلي واشربي وقري عيناً»."},{"t":"النخل باسقات لها طلع نضيد","r":[50,9,11],"n":"الماء المبارك ينبت جنات وحب الحصيد والنخل الباسقات رزقاً للعباد."},{"t":"ومن ثمرات النخيل والأعناب","r":[16,67],"n":"فرّق بين السَّكَر والرزق الحسن، وقد نزلت قبل تحريم الخمر، وفيها تمهيد له."},{"t":"كشجرة طيبة","r":[14,24,25],"n":"المثل بالشجرة الطيبة التي تؤتي أكلها كل حين، وفسرها جماعة من السلف بالنخلة."}]},{"id":"sharab","t":"العسل واللبن والماء","d":"ذكر القرآن من الأشربة العسل واللبن والماء العذب، وجعلها آيات على قدرة الله ورحمته: لبن خالص يخرج من بين فرث ودم، وعسل مختلف ألوانه من بطون النحل، وماء ينزل من المزن عذباً لا أجاجاً. ونقتصر في الشفاء على ما نصت عليه الآية والحديث الصحيح دون زيادة.","ay":[{"t":"وأوحى ربك إلى النحل","r":[16,68,69],"n":"هداية النحل إلى بيوتها ومراعيها، ثم «فيه شفاء للناس»، فختمت الآية بالدعوة إلى التفكر."},{"t":"لبناً خالصاً سائغاً للشاربين","r":[16,66],"n":"عبرة في الأنعام: يخرج اللبن صافياً من بين فرث ودم."},{"t":"أفرأيتم الماء الذي تشربون","r":[56,68,70],"n":"تذكير بأن عذوبة الماء نعمة لو شاء الله لجعله ملحاً أجاجاً، فهلا تشكرون."},{"t":"وجعلنا من الماء كل شيء حي","r":[21,30],"n":"الماء أصل الحياة كلها، وهو أول ما يُذكر من نعم الطعام والشراب."}]},{"id":"aqwat","t":"أطعمة ذكرها القرآن","d":"سمّى القرآن أطعمة بأعيانها: المن والسلوى، والبقل والقثاء والفوم والعدس والبصل، ولحم البحر الطري، ولحوم الأنعام والطير. وفي ذكرها بيان لسعة رزق الله، وأن الطيب منه مباح، وأن التطلع إلى الأدنى مع وجود الخير مذموم.","ay":[{"t":"المن والسلوى","r":[2,57],"n":"رزق بلا تعب، ثم «كلوا من طيبات ما رزقناكم»، فلم يشكروا."},{"t":"أتستبدلون الذي هو أدنى بالذي هو خير","r":[2,61],"n":"سمّت الآية خمسة أطعمة من نبات الأرض، وعاتبت على ترك الأفضل."},{"t":"لحماً طرياً من البحر","r":[16,14],"n":"تسخير البحر للأكل والحلية والسفر، ثم «ولعلكم تشكرون»."},{"t":"أُحل لكم صيد البحر وطعامه","r":[5,96],"n":"أباح الله صيد البحر وطعامه حتى للمحرم، متاعاً للمقيم والمسافر."},{"t":"ولحم طير مما يشتهون","r":[56,20,21],"n":"من نعيم أهل الجنة: فاكهة يتخيرونها ولحم طير يشتهونه."},{"t":"ومن الأنعام حمولة وفرشاً","r":[6,142],"n":"«كلوا مما رزقكم الله ولا تتبعوا خطوات الشيطان»: الأكل من الأنعام نعمة، وتحريمها بغير علم من خطوات الشيطان."}]},{"id":"halal","t":"الحلال والطيبات وما حرّم الله","d":"الأصل في الأطعمة الإباحة، وقد أمر الله الناس جميعاً أن يأكلوا مما في الأرض حلالاً طيباً، وخص المؤمنين بالأمر بالطيبات والشكر، وفصّل ما حرّم: الميتة والدم ولحم الخنزير وما أُهل لغير الله به، ثم رفع الحرج عن المضطر. وأحلّ الطيبات وحرّم الخبائث، ونهى عن تحريم ما أحل الله.","ay":[{"t":"كلوا مما في الأرض حلالاً طيباً","r":[2,168],"n":"خطاب للناس كافة، وفيه أن الأصل في الأعيان الإباحة."},{"t":"كلوا من طيبات ما رزقناكم واشكروا لله","r":[2,172,173],"n":"الأمر بالطيبات والشكر، ثم حصر المحرمات الأربع، ورفع الإثم عن المضطر غير الباغي ولا العادي."},{"t":"حُرّمت عليكم الميتة","r":[5,3],"n":"تفصيل المحرمات من المنخنقة والموقوذة والمتردية والنطيحة وما أكل السبع إلا ما ذُكّي."},{"t":"اليوم أُحل لكم الطيبات","r":[5,4,5],"n":"حلّ صيد الجوارح المعلَّمة مع ذكر اسم الله، وحلّ طعام أهل الكتاب."},{"t":"ويحل لهم الطيبات ويحرم عليهم الخبائث","r":[7,157],"n":"من صفات الرسول ﷺ في الكتب السابقة: إحلال الطيبات وتحريم الخبائث ووضع الآصار."},{"t":"إنما الخمر والميسر","r":[5,90,91],"n":"تحريم الخمر قاطعاً، وبيان علته: العداوة والبغضاء والصد عن ذكر الله وعن الصلاة."},{"t":"فكلوا مما ذُكر اسم الله عليه","r":[6,118,119],"n":"ربط الأكل بالإيمان وذكر اسم الله، وأن الله قد فصّل ما حرّم."}]},{"id":"adab","t":"آداب الطعام والاعتدال وترك الإسراف","d":"جمعت آية الأعراف قاعدة الطعام: «وكلوا واشربوا ولا تسرفوا». فالأكل مأمور به، والإسراف منهي عنه، وتحريم الطيبات على النفس تشدد مذموم. ومن الأدب: ذكر اسم الله، والأكل باليمين ومما يلي الآكل، وعدم عيب الطعام، وحمد الله بعده.","ay":[{"t":"وكلوا واشربوا ولا تسرفوا","r":[7,31,32],"n":"الأمر بالأكل والشرب، والنهي عن الإسراف، ثم الإنكار على من حرّم زينة الله والطيبات من الرزق."},{"t":"لا تحرموا طيبات ما أحل الله لكم","r":[5,87,88],"n":"الغلو في ترك المباحات اعتداء، والوسط أن يؤكل الحلال الطيب مع التقوى."},{"t":"كلوا من طيبات ما رزقناكم ولا تطغوا فيه","r":[20,81],"n":"الطغيان في الرزق: الإسراف فيه، أو الاستعانة به على المعصية، أو كفران النعمة."},{"t":"ولا تبذر تبذيراً","r":[17,26,27],"n":"المبذرون إخوان الشياطين، والتبذير إنفاق في غير حق."},{"t":"وكان بين ذلك قواماً","r":[25,67],"n":"من صفات عباد الرحمن: الاعتدال في النفقة بين الإسراف والتقتير."},{"t":"فإذا طعمتم فانتشروا","r":[33,53],"n":"أدب الضيافة: لا يُدخل البيت إلا بإذن، ولا يُطال المكث بعد الطعام."},{"t":"أن تأكلوا جميعاً أو أشتاتاً","r":[24,61],"n":"رفع الحرج في الأكل من بيوت الأقارب، والأكل مجتمعين أو متفرقين."}]},{"id":"nima","t":"الطعام نعمة تستوجب الشكر","d":"يذكّر القرآن الإنسان أن ينظر إلى طعامه: من صبّ الماء وشقّ الأرض حتى صار حباً وعنباً وزيتوناً ونخلاً، ويقرن الإطعام بالأمن في سياق المنّة، ويضرب المثل بقرية كفرت بأنعم الله فأذاقها لباس الجوع والخوف.","ay":[{"t":"فلينظر الإنسان إلى طعامه","r":[80,24,30],"n":"تأمّل رحلة اللقمة من المطر إلى المائدة يورث الشكر."},{"t":"الذي أطعمهم من جوع وآمنهم من خوف","r":[106,3,4],"n":"الإطعام والأمن من أكبر النعم الموجبة لعبادة رب البيت."},{"t":"لباس الجوع والخوف","r":[16,112],"n":"كفران النعمة سبب لزوالها؛ الرزق الرغد يتبدل جوعاً."},{"t":"كلوا من رزق ربكم واشكروا له","r":[34,15],"n":"جنتا سبأ: «بلدة طيبة ورب غفور»، ثم أعرضوا فبُدّلوا."},{"t":"وارزقهم من الثمرات لعلهم يشكرون","r":[14,37],"n":"دعوة إبراهيم لذريته بواد غير ذي زرع، فجُبيت إليه ثمرات كل شيء."},{"t":"وآية لهم الأرض الميتة","r":[36,33,35],"n":"إحياء الأرض بالحب والنخيل والأعناب «ليأكلوا من ثمره وما عملته أيديهم أفلا يشكرون»."}]},{"id":"itam","t":"إطعام الطعام","d":"جعل القرآن إطعام الطعام من صفات الأبرار، وقرنه باقتحام العقبة، وجعل ترك الحض على طعام المسكين من صفات المكذبين بالدين، وشرعه في الكفارات والفدية والهدي، وجعله من أسباب النجاة.","ay":[{"t":"ويطعمون الطعام على حبه","r":[76,8,9],"n":"إطعام المسكين واليتيم والأسير مع حب الطعام، ابتغاء وجه الله وحده."},{"t":"أو إطعام في يوم ذي مسغبة","r":[90,11,16],"n":"من اقتحام العقبة: فك الرقبة وإطعام اليتيم القريب والمسكين ذي المتربة."},{"t":"ولا يحض على طعام المسكين","r":[107,1,3],"n":"ترك الحض على الإطعام قرين دعّ اليتيم والتكذيب بالدين."},{"t":"وأطعموا البائس الفقير","r":[22,28],"n":"من مقاصد الهدي والأضاحي: الأكل منها وإطعام الفقير."},{"t":"وأطعموا القانع والمعتر","r":[22,36],"n":"إطعام من يسأل ومن لا يسأل، ثم «لعلكم تشكرون»."},{"t":"إطعام عشرة مساكين","r":[5,89],"n":"كفارة اليمين تبدأ بالإطعام من أوسط ما يُطعَم الأهل."}]},{"id":"qasas","t":"الطعام في قصص القرآن","d":"للطعام حضور في قصص القرآن: الشجرة التي نُهي عنها آدم، وضيافة إبراهيم بالعجل الحنيذ، ورؤيا الخبز في سجن يوسف وتدبيره للقمح، ومائدة الحواريين، وأزكى الطعام عند أصحاب الكهف، وحوت موسى وفتاه، ويقطين يونس.","ay":[{"t":"وكلا منها رغداً حيث شئتما","r":[2,35],"n":"أول أمر ونهي في قصة آدم كان في الطعام: إباحة واسعة وحِمى واحد."},{"t":"فجاء بعجل حنيذ","r":[11,69,70],"n":"المبادرة إلى إكرام الضيف بأطيب الطعام من أخلاق الأنبياء."},{"t":"فما لبثتم في سنبله","r":[12,47,49],"n":"تدبير يوسف: الادخار في سني الرخاء والأكل بقدر، وهي خطة اقتصادية في الطعام."},{"t":"المائدة","r":[5,112,115],"n":"سأل الحواريون مائدة من السماء لتطمئن قلوبهم، فجاءت النعمة ومعها شدة المسؤولية."},{"t":"فلينظر أيها أزكى طعاماً","r":[18,19],"n":"تحرّي الطعام الحلال الطيب حتى في الشدة، مع التلطف والحذر."},{"t":"آتنا غداءنا","r":[18,62,63],"n":"زاد موسى وفتاه في رحلة طلب العلم، والحوت علامة اللقاء."},{"t":"شجرة من يقطين","r":[37,145,146],"n":"رحمة الله بيونس بعد خروجه من بطن الحوت سقيماً."}]},{"id":"akhira","t":"طعام أهل الجنة وطعام أهل النار","d":"وصف القرآن نعيم الجنة بأنهار من ماء ولبن وعسل مصفى، وفاكهة مما يتخيرون، ولحم طير مما يشتهون، وقطوف دانية؛ وفي المقابل طعام أهل النار: الزقوم، والضريع، والغسلين، وشراب الحميم، تحذيراً وترغيباً.","ay":[{"t":"أنهار من ماء ولبن وخمر وعسل","r":[47,15],"n":"أنهار الجنة لا تتغير، ولهم فيها من كل الثمرات ومغفرة من ربهم."},{"t":"قطوفها دانية","r":[69,21,24],"n":"«كلوا واشربوا هنيئاً بما أسلفتم في الأيام الخالية»: نعيم الجنة جزاء عمل الدنيا."},{"t":"وأمددناهم بفاكهة ولحم","r":[52,22,23],"n":"فاكهة ولحم مما يشتهون، وكأس لا لغو فيها ولا تأثيم."},{"t":"في سدر مخضود وطلح منضود","r":[56,27,33],"n":"ثمار أصحاب اليمين لا مقطوعة ولا ممنوعة."},{"t":"إن شجرت الزقوم طعام الأثيم","r":[44,43,46],"n":"طعام أهل النار يغلي في البطون كغلي الحميم."},{"t":"ليس لهم طعام إلا من ضريع","r":[88,6,7],"n":"طعام لا يسمن ولا يغني من جوع."},{"t":"ولا يحض على طعام المسكين","r":[69,33,37],"n":"من أسباب العذاب ترك الحض على إطعام المسكين، وطعامهم الغسلين."}]}],"h":[{"id":"tasmiya","t":"سمِّ الله وكُل بيمينك","x":"كُنْتُ غُلاَمًا فِي حَجْرِ رَسُولِ اللَّهِ صلى الله عليه وسلم وَكَانَتْ يَدِي تَطِيشُ فِي الصَّحْفَةِ فَقَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم \" يَا غُلاَمُ سَمِّ اللَّهَ، وَكُلْ بِيَمِينِكَ وَكُلْ مِمَّا يَلِيكَ\"","src":[["bukhari","5376"],["muslim","2022"]],"gr":"صحيح: متفق عليه","dg":"","f":"ثلاثة آداب جامعة: التسمية، والأكل باليمين، والأكل مما يلي الآكل؛ مع رفق النبي ﷺ في تعليم الصغير.","en":"Umar ibn Abi Salamah said: I was a boy in the care of the Messenger of Allah ﷺ, and my hand would wander around the dish. The Messenger of Allah ﷺ said to me: \"Young boy, mention the name of Allah, eat with your right hand, and eat from what is in front of you.\"","ch":"adab"},{"id":"aib","t":"ما عاب طعاماً قط","x":"مَا عَابَ النَّبِيُّ صلى الله عليه وسلم طَعَامًا قَطُّ، إِنِ اشْتَهَاهُ أَكَلَهُ، وَإِنْ كَرِهَهُ تَرَكَهُ","src":[["bukhari","5409"],["muslim","2064"]],"gr":"صحيح: متفق عليه","dg":"","f":"من الأدب ترك ذمّ الطعام؛ فإن اشتهاه أكله وإلا تركه دون عيب.","en":"Abu Hurairah said: The Prophet ﷺ never found fault with any food. If he desired it he ate it, and if he disliked it he left it.","ch":"adab"},{"id":"wia","t":"ما ملأ آدمي وعاء شراً من بطن","x":"مَا مَلأَ آدَمِيٌّ وِعَاءً شَرًّا مِنْ بَطْنٍ بِحَسْبِ ابْنِ آدَمَ أُكُلاَتٌ يُقِمْنَ صُلْبَهُ فَإِنْ كَانَ لاَ مَحَالَةَ فَثُلُثٌ لِطَعَامِهِ وَثُلُثٌ لِشَرَابِهِ وَثُلُثٌ لِنَفَسِهِ","src":[["tirmidhi","2380"]],"gr":"","dg":"الألباني: صحيح؛ أحمد شاكر: صحيح؛ بشار عواد معروف: حسن صحيح؛ زبير علي زئي: صحيح","f":"ميزان الاعتدال: لقيمات تقيم الصلب، فإن زاد فلا يتجاوز الثلث للطعام.","en":"\"A human being fills no vessel worse than his stomach. A few morsels that keep his back upright are sufficient for the son of Adam. If he must, then one third for his food, one third for his drink and one third for his breath.\"","ch":"adab"},{"id":"mia","t":"المؤمن يأكل في معى واحد","x":"يَأْكُلُ الْمُسْلِمُ فِي مِعًى وَاحِدٍ، وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ","src":[["bukhari","5396"],["muslim","2062"]],"gr":"صحيح: متفق عليه","dg":"","f":"حثّ على القناعة وقلة الشره، وأن همّ المؤمن ليس في بطنه.","en":"\"The Muslim eats in one intestine, and the disbeliever eats in seven intestines.\"","ch":"adab"},{"id":"laq","t":"لعق الأصابع والصحفة","x":"أَمَرَ بِلَعْقِ الأَصَابِعِ وَالصَّحْفَةِ وَقَالَ \" إِنَّكُمْ لاَ تَدْرُونَ فِي أَيِّهِ الْبَرَكَةُ\"","src":[["muslim","2033"]],"gr":"صحيح: رواه مسلم","dg":"","f":"احترام النعمة وترك إهدار شيء منها، فالبركة قد تكون في آخر لقمة.","en":"The Prophet ﷺ commanded licking the fingers and the dish, and said: \"You do not know in which part the blessing lies.\"","ch":"adab"},{"id":"ittika","t":"لا آكل متكئاً","x":"لاَ آكُلُ مُتَّكِئًا","src":[["bukhari","5398"]],"gr":"صحيح: رواه البخاري","dg":"","f":"من هدي النبي ﷺ التواضع في جلسة الطعام.","en":"\"I do not eat while reclining.\"","ch":"adab"},{"id":"aniya","t":"لا تشربوا في آنية الذهب والفضة","x":"لاَ تَشْرَبُوا فِي آنِيَةِ الذَّهَبِ وَالْفِضَّةِ، وَلاَ تَلْبَسُوا الْحَرِيرَ وَالدِّيبَاجَ، فَإِنَّهَا لَهُمْ فِي الدُّنْيَا وَلَكُمْ فِي الآخِرَةِ","src":[["bukhari","5633"],["muslim","2067"]],"gr":"صحيح: متفق عليه","dg":"","f":"تحريم الأكل والشرب في آنية الذهب والفضة، وهو من الترف الذي نُهي عنه.","en":"\"Do not drink from vessels of gold and silver, and do not wear silk or brocade, for they are for them in this world and for you in the Hereafter.\"","ch":"adab"},{"id":"tayyib","t":"إن الله طيب لا يقبل إلا طيباً","x":"أَيُّهَا النَّاسُ إِنَّ اللَّهَ طَيِّبٌ لاَ يَقْبَلُ إِلاَّ طَيِّبًا وَإِنَّ اللَّهَ أَمَرَ الْمُؤْمِنِينَ بِمَا أَمَرَ بِهِ الْمُرْسَلِينَ فَقَالَ { يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ} وَقَالَ { يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ} \" . ثُمَّ ذَكَرَ الرَّجُلَ يُطِيلُ السَّفَرَ أَشْعَثَ أَغْبَرَ يَمُدُّ يَدَيْهِ إِلَى السَّمَاءِ يَا رَبِّ يَا رَبِّ وَمَطْعَمُهُ حَرَامٌ وَمَشْرَبُهُ حَرَامٌ وَمَلْبَسُهُ حَرَامٌ وَغُذِيَ بِالْحَرَامِ فَأَنَّى يُسْتَجَابُ لِذَلِكَ\"","src":[["muslim","1015"]],"gr":"صحيح: رواه مسلم","dg":"","f":"المطعم الحلال من أسباب قبول الدعاء، والحرام من موانعه؛ واستشهد النبي ﷺ بآيتين في الأمر بالطيبات.","en":"\"O people, Allah is good and accepts only what is good. Allah has commanded the believers with what He commanded the messengers: 'O messengers, eat from the good things and do righteousness', and He said: 'O you who believe, eat from the good things We have provided you.'\" Then he mentioned a man who travels long, dishevelled and dusty, stretching his hands to the sky: \"O Lord, O Lord\", while his food is unlawful, his drink is unlawful, his clothing is unlawful and he has been nourished with the unlawful, so how can he be answered?","ch":"halal"},{"id":"bayyin","t":"الحلال بيّن والحرام بيّن","x":"الْحَلاَلُ بَيِّنٌ وَالْحَرَامُ بَيِّنٌ، وَبَيْنَهُمَا مُشَبَّهَاتٌ لاَ يَعْلَمُهَا كَثِيرٌ مِنَ النَّاسِ، فَمَنِ اتَّقَى الْمُشَبَّهَاتِ اسْتَبْرَأَ لِدِيِنِهِ وَعِرْضِهِ، وَمَنْ وَقَعَ فِي الشُّبُهَاتِ كَرَاعٍ يَرْعَى حَوْلَ الْحِمَى، يُوشِكُ أَنْ يُوَاقِعَهُ. أَلاَ وَإِنَّ لِكُلِّ مَلِكٍ حِمًى، أَلاَ إِنَّ حِمَى اللَّهِ فِي أَرْضِهِ مَحَارِمُهُ، أَلاَ وَإِنَّ فِي الْجَسَدِ مُضْغَةً إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ، وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ. أَلاَ وَهِيَ الْقَلْبُ","src":[["bukhari","52"],["muslim","1599"]],"gr":"صحيح: متفق عليه","dg":"","f":"قاعدة الورع في المطاعم وغيرها: اتقاء المشتبهات استبراء للدين والعرض.","en":"\"The lawful is clear and the unlawful is clear, and between them are doubtful matters that many people do not know. Whoever guards against doubtful matters protects his religion and honour, and whoever falls into them is like a shepherd grazing around a sanctuary, about to stray into it. Every king has a sanctuary, and Allah's sanctuary on His earth is what He has forbidden. In the body there is a morsel of flesh which, if sound, the whole body is sound, and if corrupt, the whole body is corrupt: it is the heart.\"","ch":"halal"},{"id":"nab","t":"كل ذي ناب من السباع وذي مخلب من الطير","x":"نَهَى رَسُولُ اللَّهِ صلى الله عليه وسلم عَنْ كُلِّ ذِي نَابٍ مِنَ السِّبَاعِ وَعَنْ كُلِّ ذِي مِخْلَبٍ مِنَ الطَّيْرِ","src":[["muslim","1934"]],"gr":"صحيح: رواه مسلم","dg":"","f":"بيّنت السنة من الخبائث المحرمة: كل سبع ذي ناب، وكل طائر ذي مخلب.","en":"Ibn Abbas said: The Messenger of Allah ﷺ forbade every predator with fangs and every bird with talons.","ch":"halal"},{"id":"bahr","t":"هو الطهور ماؤه الحل ميتته","x":"سَأَلَ رَجُلٌ النَّبِيَّ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا نَرْكَبُ الْبَحْرَ وَنَحْمِلُ مَعَنَا الْقَلِيلَ مِنَ الْمَاءِ فَإِنْ تَوَضَّأْنَا بِهِ عَطِشْنَا أَفَنَتَوَضَّأُ بِمَاءِ الْبَحْرِ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم \" هُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مَيْتَتُهُ\"","src":[["abudawud","83"],["tirmidhi","69"]],"gr":"","dg":"الألباني: صحيح؛ شعيب الأرنؤوط: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: إسناده صحيح","f":"ميتة البحر حلال، فكل ما يعيش في البحر ولا يعيش إلا فيه حلال وإن مات فيه.","en":"A man asked the Prophet ﷺ: \"O Messenger of Allah, we travel by sea and carry little water; if we use it for ablution we go thirsty. May we perform ablution with sea water?\" The Messenger of Allah ﷺ said: \"Its water is purifying and its dead are lawful.\"","ch":"halal"},{"id":"yad","t":"خير الطعام ما كان من عمل اليد","x":"مَا أَكَلَ أَحَدٌ طَعَامًا قَطُّ خَيْرًا مِنْ أَنْ يَأْكُلَ مِنْ عَمَلِ يَدِهِ، وَإِنَّ نَبِيَّ اللَّهِ دَاوُدَ ـ عَلَيْهِ السَّلاَمُ ـ كَانَ يَأْكُلُ مِنْ عَمَلِ يَدِهِ","src":[["bukhari","2072"]],"gr":"صحيح: رواه البخاري","dg":"","f":"طيب المطعم يبدأ من طيب الكسب، وكان داود عليه السلام يأكل من عمل يده.","en":"\"No one has ever eaten food better than eating from the work of his own hands, and the Prophet of Allah Dawud (peace be upon him) used to eat from the work of his hands.\"","ch":"halal"},{"id":"yarda","t":"إن الله ليرضى عن العبد يأكل الأكلة فيحمده عليها","x":"إِنَّ اللَّهَ لَيَرْضَى عَنِ الْعَبْدِ أَنْ يَأْكُلَ الأَكْلَةَ فَيَحْمَدَهُ عَلَيْهَا أَوْ يَشْرَبَ الشَّرْبَةَ فَيَحْمَدَهُ عَلَيْهَا","src":[["muslim","2734"]],"gr":"صحيح: رواه مسلم","dg":"","f":"الحمد بعد الطعام والشراب عبادة يسيرة ينال بها العبد رضا الله.","en":"\"Allah is pleased with the servant who eats a meal and praises Him for it, or drinks a drink and praises Him for it.\"","ch":"nima"},{"id":"hamd","t":"الحمد بعد الطعام","x":"كَانَ إِذَا رَفَعَ مَائِدَتَهُ قَالَ \" الْحَمْدُ لِلَّهِ كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، غَيْرَ مَكْفِيٍّ، وَلاَ مُوَدَّعٍ وَلاَ مُسْتَغْنًى عَنْهُ، رَبَّنَا\"","src":[["bukhari","5458"]],"gr":"صحيح: رواه البخاري","dg":"","f":"ذكر مأثور يقال عند رفع الطعام، فيه الحمد والاعتراف بدوام الحاجة إلى الله.","en":"When his table was lifted, the Prophet ﷺ would say: \"Praise be to Allah, abundant, good and blessed praise; [our Lord] is not in need of being fed, nor is it bid farewell to, nor can we dispense with it, our Lord.\"","ch":"nima"},{"id":"tutim","t":"تطعم الطعام وتقرأ السلام","x":"أَنَّ رَجُلاً، سَأَلَ النَّبِيَّ صلى الله عليه وسلم أَىُّ الإِسْلاَمِ خَيْرٌ قَالَ \" تُطْعِمُ الطَّعَامَ، وَتَقْرَأُ السَّلاَمَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ\"","src":[["bukhari","12"],["muslim","39"]],"gr":"صحيح: متفق عليه","dg":"","f":"إطعام الطعام من خير خصال الإسلام، وهو يشمل الصدقة والضيافة والهدية.","en":"A man asked the Prophet ﷺ: \"Which [deed in] Islam is best?\" He said: \"That you feed others and greet with peace those you know and those you do not know.\"","ch":"itam"},{"id":"ithnayn","t":"طعام الاثنين كافي الثلاثة","x":"طَعَامُ الاِثْنَيْنِ كَافِي الثَّلاَثَةِ، وَطَعَامُ الثَّلاَثَةِ كَافِي الأَرْبَعَةِ","src":[["bukhari","5392"],["muslim","2058"]],"gr":"صحيح: متفق عليه","dg":"","f":"الاجتماع على الطعام بركة، وفيه حث على المواساة وإشراك الضيف.","en":"\"The food of two is enough for three, and the food of three is enough for four.\"","ch":"itam"},{"id":"tamr","t":"بيت لا تمر فيه","x":"يَا عَائِشَةُ بَيْتٌ لاَ تَمْرَ فِيهِ جِيَاعٌ أَهْلُهُ يَا عَائِشَةُ بَيْتٌ لاَ تَمْرَ فِيهِ جِيَاعٌ أَهْلُهُ أَوْ جَاعَ أَهْلُهُ","src":[["muslim","2046"]],"gr":"صحيح: رواه مسلم","dg":"","f":"منزلة التمر قوتاً أساسياً في بيوت أهل المدينة.","en":"\"O Aishah, a house without dates, its people are hungry. O Aishah, a house without dates, its people are hungry\" (or: its people have gone hungry). He said it two or three times.","ch":"nakhl"},{"id":"ajwa","t":"سبع تمرات عجوة","x":"مَنْ تَصَبَّحَ كُلَّ يَوْمٍ سَبْعَ تَمَرَاتٍ عَجْوَةً لَمْ يَضُرُّهُ فِي ذَلِكَ الْيَوْمِ سُمٌّ وَلاَ سِحْرٌ","src":[["bukhari","5445"],["muslim","2047"]],"gr":"صحيح: متفق عليه","dg":"","f":"نذكر نص الحديث كما ورد دون زيادة عليه؛ وهو من خبر النبي ﷺ الذي يؤمن به المسلم، ولا يغني عن الأخذ بالأسباب.","en":"\"Whoever has seven 'ajwah dates every morning, neither poison nor magic will harm him that day.\"","ch":"nakhl"},{"id":"qiththa","t":"الرطب بالقثاء","x":"رَأَيْتُ النَّبِيَّ صلى الله عليه وسلم يَأْكُلُ الرُّطَبَ بِالْقِثَّاءِ","src":[["bukhari","5440"],["muslim","2043"]],"gr":"صحيح: متفق عليه","dg":"","f":"الجمع بين صنفين من الطعام مباح، وكان من هدي النبي ﷺ.","en":"Abdullah ibn Ja'far said: I saw the Prophet ﷺ eating fresh dates with cucumber.","ch":"aqwat"},{"id":"kamaa","t":"الكمأة من المن","x":"الْكَمْأَةُ مِنَ الْمَنِّ، وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ","src":[["bukhari","4478"],["muslim","2049"]],"gr":"صحيح: متفق عليه","dg":"","f":"ربط النبي ﷺ الكمأة بالمن المذكور في القرآن، وهي رزق ينبت دون زرع. ونقتصر على لفظ الحديث دون زيادة.","en":"\"Truffles are a kind of manna, and their water is a cure for the eye.\"","ch":"aqwat"},{"id":"khall","t":"نعم الأدم الخل","x":"سَأَلَ أَهْلَهُ الأُدُمَ فَقَالُوا مَا عِنْدَنَا إِلاَّ خَلٌّ . فَدَعَا بِهِ فَجَعَلَ يَأْكُلُ بِهِ وَيَقُولُ \" نِعْمَ الأُدُمُ الْخَلُّ نِعْمَ الأُدُمُ الْخَلُّ\"","src":[["muslim","2052"]],"gr":"صحيح: رواه مسلم","dg":"","f":"الرضا بالموجود من الطعام والثناء عليه وإن كان يسيراً.","en":"The Prophet ﷺ asked his family for something to eat with bread. They said: \"We have nothing but vinegar.\" He called for it and began eating with it, saying: \"What a good condiment vinegar is! What a good condiment vinegar is!\"","ch":"aqwat"},{"id":"asal","t":"صدق الله وكذب بطن أخيك","x":"جَاءَ رَجُلٌ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَ إِنَّ أَخِي اسْتَطْلَقَ بَطْنُهُ. فَقَالَ \" اسْقِهِ عَسَلاً \". فَسَقَاهُ. فَقَالَ إِنِّي سَقَيْتُهُ فَلَمْ يَزِدْهُ إِلاَّ اسْتِطْلاَقًا. فَقَالَ \" صَدَقَ اللَّهُ وَكَذَبَ بَطْنُ أَخِيكَ\"","src":[["bukhari","5716"],["muslim","2217"]],"gr":"صحيح: متفق عليه","dg":"","f":"تصديق خبر القرآن «فيه شفاء للناس»، مع تكرار الأخذ بالسبب. ولا يُستدل به على ترك مراجعة الطبيب.","en":"A man came to the Prophet ﷺ and said: \"My brother has diarrhoea.\" He said: \"Give him honey to drink.\" He did, then said: \"I gave him some, but it only increased.\" He said: \"Allah has spoken the truth, and your brother's stomach has lied.\"","ch":"sharab"},{"id":"halwa","t":"كان يحب الحلواء والعسل","x":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُحِبُّ الْحَلْوَاءَ وَالْعَسَلَ","src":[["bukhari","5431"]],"gr":"صحيح: رواه البخاري","dg":"","f":"محبة الطيبات المباحة لا تنافي الزهد.","en":"Aishah said: The Messenger of Allah ﷺ loved sweets and honey.","ch":"sharab"},{"id":"zayt","t":"كلوا الزيت وادّهنوا به","x":"كُلُوا الزَّيْتَ وَادَّهِنُوا بِهِ فَإِنَّهُ مِنْ شَجَرَةٍ مُبَارَكَةٍ","src":[["tirmidhi","1852"]],"gr":"","dg":"الألباني: صحيح؛ أحمد شاكر: صحيح لغيره؛ زبير علي زئي: صحيح","f":"وصف الزيتون بالبركة موافق لوصفه في القرآن «من شجرة مباركة زيتونة». وحكم الحديث من المحدثين كما ورد في النسخة المضمّنة.","en":"\"Eat olive oil and anoint yourselves with it, for it is from a blessed tree.\"","ch":"fawakih"}],"q":[{"ch":"fawakih","w":"السعدي","bk":"saadi","s":95,"ay":1,"x":"{التين}: هو التين المعروف، وكذلك {الزَّيتون}؛ أقسم بهاتين الشجرتين؛ لكثرة منافع شجرهما وثمرهما، ولأنَّ سلطانهما في أرض الشام محلِّ نبوَّة عيسى ابن مريم عليه السلام","n":"وجه القسم بالتين والزيتون.","en":"\"The fig is the familiar fig, and likewise the olive. He swore by these two trees because of the many benefits of their trees and fruit, and because they flourish in the land of al-Sham, the place of the prophethood of 'Isa son of Maryam, peace be upon him.\""},{"ch":"fawakih","w":"ابن كثير","bk":"ibnkathir","s":95,"ay":1,"x":"وَقَالَ مُجَاهِدٌ: هُوَ تِينِكُمْ هَذَا. ﴿وَالزَّيْتُونِ﴾ قَالَ كَعْبُ الْأَحْبَارِ، وَقَتَادَةُ، وَابْنُ زَيْدٍ، وَغَيْرُهُمْ: هُوَ مَسْجِدُ بَيْتِ الْمَقْدِسِ. وَقَالَ مُجَاهِدٌ، وَعِكْرِمَةُ: هُوَ هَذَا الزَّيْتُونُ الَّذِي تَعْصِرُونَ","n":"من أقوال السلف في المراد بالتين والزيتون.","en":"\"Mujahid said: it is this fig of yours. ... Ka'b al-Ahbar, Qatadah, Ibn Zayd and others said about the olive: it is the mosque of Bayt al-Maqdis. Mujahid and 'Ikrimah said: it is this olive that you press.\""},{"ch":"sharab","w":"السعدي","bk":"saadi","s":16,"ay":66,"x":"حيث أسقاكم من بطونها المشتملة على الفَرْث والدَّم، فأخرج من بين ذلك لبناً خالصاً من الكدر سائغاً للشاربين للذَّته ولأنه يُسقي ويغذي؛ فهل هذه إلاَّ قدرة إلهيَّة لا أمور طبيعيَّة؟!","n":"اللبن آية على القدرة.","en":"\"For He gives you to drink from their bellies, which contain digested food and blood, and brings out from between them pure milk, free of impurity, pleasant to drinkers for its taste and because it quenches and nourishes. Is this anything but divine power rather than mere nature?!\""},{"ch":"sharab","w":"ابن كثير","bk":"ibnkathir","s":16,"ay":69,"x":"وَقَوْلُهُ: ﴿فِيهِ شِفَاءٌ لِلنَّاسِ﴾ أَيْ: فِي الْعَسَلِ شِفَاءٌ لِلنَّاسِ مِنْ أَدْوَاءٍ تَعْرِضُ لَهُمْ","n":"المراد بالشفاء في الآية: العسل، على ظاهر السياق.","en":"\"His saying 'in it is healing for people' means: in honey there is healing for people from ailments that befall them.\""},{"ch":"aqwat","w":"السعدي","bk":"saadi","s":2,"ay":57,"x":"وهو: اسم جامع لكل رزق [حسن] يحصل بلا تعب، ومنه الزنجبيل والكمأة، والخبز، وغير ذلك، {والسلوى}؛ طائر صغير يقال له: السماني طيب اللحم","n":"تفسير المن والسلوى.","en":"\"Manna is a comprehensive name for every good provision obtained without toil, including ginger, truffles, bread and other things; and quails are a small bird called al-sumana, with good meat.\""},{"ch":"halal","w":"السعدي","bk":"saadi","s":2,"ay":168,"x":"ففي هذه الآية دليل على أن الأصل في الأعيان الإباحة أكلاً وانتفاعاً وأن المحرم نوعان: إما محرم لذاته وهو الخبيث الذي هو ضد الطيب، وإما محرم لما عرض له وهو المحرم لتعلق حق الله أو حق عباده به، وهو ضد الحلال","n":"قاعدة الأصل في الأطعمة.","en":"\"This verse is evidence that the default ruling for things is permission, both to eat and to benefit from them, and that the forbidden is of two kinds: forbidden in itself, which is the foul, the opposite of the good; and forbidden because of something attached to it, being connected to a right of Allah or of His servants, which is the opposite of the lawful.\""},{"ch":"adab","w":"السعدي","bk":"saadi","s":7,"ay":31,"x":"والإسراف إما أن يكون بالزيادة على القدر الكافي والشره في المأكولات التي تضر بالجسم، وإما أن يكون بزيادة الترفُّه والتنوُّق في المآكل والمشارب واللباس، وإما بتجاوز الحلال إلى الحرام. {إنَّه لا يحبُّ المسرفين}: فإن السرف يبغضه الله، ويضرُّ بدن الإنسان ومعيشته، حتى إنه ربما أدَّت به الحالُ إلى أن يعجز عما يجب عليه من النفقات. ففي هذه الآية الكريمة الأمر بتناول الأكل والشرب والنهي عن تركهما وعن الإسراف فيهما","n":"أنواع الإسراف في الطعام والشراب.","en":"\"Excess is either exceeding the sufficient amount and greed for foods that harm the body, or excessive luxury and fastidiousness in food, drink and clothing, or going beyond the lawful to the unlawful. 'He does not love the excessive': excess is hated by Allah and harms a person's body and livelihood, until it may leave him unable to meet his obligatory expenses. So this noble verse contains the command to eat and drink and the prohibition of abandoning them or being excessive in them.\""},{"ch":"adab","w":"السعدي","bk":"saadi","s":5,"ay":87,"x":"من المطاعم والمشارب؛ فإنَّها نِعَمٌ أنعم الله بها عليكم؛ فاحْمَدوه إذ أحلَّها لكم واشكُروه، ولا تَرُدُّوا نعمته بكفرها، أو عدم قبولها، أو اعتقاد تحريمها، فتجمعون بذلك بين القولِ على اللهِ الكذبَ وكفر النعمة، واعتقاد الحلال الطيِّب حراماً خبيثاً؛ فإنَّ هذا من الاعتداء","n":"تحريم الحلال على النفس اعتداء.","en":"\"...of foods and drinks, for they are blessings Allah has granted you, so praise Him for making them lawful and thank Him, and do not reject His blessing by ingratitude, by refusing it or by believing it forbidden, thereby combining lying about Allah, ingratitude, and believing the lawful and good to be forbidden and foul; for this is transgression.\""},{"ch":"nima","w":"السعدي","bk":"saadi","s":80,"ay":24,"x":"ثم أرشده الله إلى النظر والتفكُّر في طعامه، وكيف وصل إليه بعدما تكرَّرت عليه طبقاتٌ عديدةٌ ويسَّره [اللَّهُ] له؛ فقال:{فلينظُرِ الإنسانُ إلى طعامه. أنَّا صَبَبۡنا الماء صَبًّا}؛ أي: أنزلنا المطر على الأرض بكثرة {ثم شَقَقۡنا الأرض} للنبات {شقًّا. فأنبَتۡنا فيها}: أصنافاً مصنَّفة من أنواع الأطعمة اللذيذة والأقوات الشهيَّة، {حبًّا}: وهذا شاملٌ لسائر الحبوب على اختلاف أصنافها، {وعنباً وقضباً}: وهو القتُّ، {وزيتوناً ونخلاً}: وخصَّ هذه الأربعة لكثرة فوائدها ومنافعها، {وحدائق غُلۡباً}؛ أي: بساتين فيها الأشجار الكثيرة الملتفَّة ، {وفاكهةً وأبًّا}: الفاكهة ما يتفكَّه فيه الإنسان من تينٍ وعنبٍ وخوخٍ ورمانٍ وغير ذلك. والأبُّ ما تأكله البهائم والأنعام، ولهذا قال:{متاعاً لكم ولأنعامكم}: التي خلقها الله وسخَّرَها لكم. فمن نظر في هذه النعم؛ أوجب له ذلك شكر ربِّه وبذلَ الجهد في الإنابة إليه والإقبال على طاعته والتَّصديق لأخباره","n":"تأمل رحلة الطعام.","en":"\"Then Allah guided him to look and reflect on his food, and how it reached him after passing through many stages... 'grapes and fodder, olives and palms': He singled out these four for their many benefits... Whoever looks at these blessings, that will oblige him to thank his Lord, strive to turn to Him, devote himself to obeying Him and believe His reports.\""},{"ch":"itam","w":"السعدي","bk":"saadi","s":76,"ay":8,"x":"{ويطعِمونَ الطَّعامَ على حبِّه}؛ أي: وهم في حال يحبُّون فيها المال والطعام، لكنَّهم قدَّموا محبَّة الله على محبَّة نفوسهم، ويتحرَّوْن في إطعامهم أولى الناس وأحوجَهم، {مسكيناً ويتيماً وأسيراً}: ويقصدون بإنفاقهم وإطعامهم وجهَ الله تعالى، ويقولون بلسان الحال:{إنَّما نطعِمُكم لوجه الله لا نريدُ منكم جزاءً ولا شكوراً}؛ أي: لا جزاءً ماليًّا ولا ثناءً قوليًّا","n":"صفة إطعام الأبرار.","en":"\"'They give food despite loving it': in a state in which they love wealth and food, yet they put love of Allah before love of themselves, and seek out the most deserving and needy to feed... seeking by their spending and feeding the face of Allah, saying by their state: 'We feed you only for the face of Allah; we want from you neither reward nor thanks', neither material reward nor verbal praise.\""},{"ch":"akhira","w":"السعدي","bk":"saadi","s":47,"ay":15,"x":"{وأنهار من لبنٍ لم يتغيَّر طعمُه}: بحموضة ولا غيرها، {وأنهار من خمرٍ لَذَّةٍ للشاربين}؛ أي: يلتذُّ بها شاربه لذةً عظيمةً، لا كخمر الدنيا الذي يُكره مذاقُه ويُصَدِّع الرأس ويغوِّلُ العقلَ، {وأنهار من عسل مصفًّى}: من شمعه وسائر أوساخه. {ولهم فيها من كلِّ الثمرات}: من نخيل وعنبٍ وتفاح ورمانٍ وأترجٍّ وتينٍ وغير ذلك ممَّا لا نظير له في الدُّنيا","n":"وصف أنهار الجنة وثمارها.","en":"\"'Rivers of milk whose taste never changes', neither by souring nor otherwise... 'and rivers of purified honey', purified of its wax and all impurities. 'And for them therein is every kind of fruit': palms, grapes, apples, pomegranates, citrons, figs and others, unlike anything in this world.\""}],"ay":{"41":"وَقُلۡنَا يَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ","63":"وَظَلَّلۡنَا عَلَيۡكُمُ ٱلۡغَمَامَ وَأَنزَلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ","67":"وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نَّصۡبِرَ عَلَىٰ طَعَامٖ وَٰحِدٖ فَٱدۡعُ لَنَا رَبَّكَ يُخۡرِجۡ لَنَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ مِنۢ بَقۡلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَاۖ قَالَ أَتَسۡتَبۡدِلُونَ ٱلَّذِي هُوَ أَدۡنَىٰ بِٱلَّذِي هُوَ خَيۡرٌۚ ٱهۡبِطُواْ مِصۡرٗا فَإِنَّ لَكُم مَّا سَأَلۡتُمۡۗ وَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ ٱلۡحَقِّۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ","174":"يَٰٓأَيُّهَا ٱلنَّاسُ كُلُواْ مِمَّا فِي ٱلۡأَرۡضِ حَلَٰلٗا طَيِّبٗا وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٌ","178":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَٱشۡكُرُواْ لِلَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ","179":"إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيۡرِ ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ","671":"حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفٖ لِّإِثۡمٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","672":"يَسۡـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمۡۖ قُلۡ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَمَا عَلَّمۡتُم مِّنَ ٱلۡجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُۖ فَكُلُواْ مِمَّآ أَمۡسَكۡنَ عَلَيۡكُمۡ وَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهِۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ","673":"ٱلۡيَوۡمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُۖ وَطَعَامُ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حِلّٞ لَّكُمۡ وَطَعَامُكُمۡ حِلّٞ لَّهُمۡۖ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلۡمُؤۡمِنَٰتِ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّ مُحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِيٓ أَخۡدَانٖۗ وَمَن يَكۡفُرۡ بِٱلۡإِيمَٰنِ فَقَدۡ حَبِطَ عَمَلُهُۥ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ","755":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحَرِّمُواْ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ","756":"وَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗاۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ أَنتُم بِهِۦ مُؤۡمِنُونَ","757":"لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلۡأَيۡمَٰنَۖ فَكَفَّٰرَتُهُۥٓ إِطۡعَامُ عَشَرَةِ مَسَٰكِينَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِيكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِيرُ رَقَبَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖۚ ذَٰلِكَ كَفَّٰرَةُ أَيۡمَٰنِكُمۡ إِذَا حَلَفۡتُمۡۚ وَٱحۡفَظُوٓاْ أَيۡمَٰنَكُمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَشۡكُرُونَ","758":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ فَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ","759":"إِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ وَيَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ","764":"أُحِلَّ لَكُمۡ صَيۡدُ ٱلۡبَحۡرِ وَطَعَامُهُۥ مَتَٰعٗا لَّكُمۡ وَلِلسَّيَّارَةِۖ وَحُرِّمَ عَلَيۡكُمۡ صَيۡدُ ٱلۡبَرِّ مَا دُمۡتُمۡ حُرُمٗاۗ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ","780":"إِذۡ قَالَ ٱلۡحَوَارِيُّونَ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ هَلۡ يَسۡتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِۖ قَالَ ٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ","781":"قَالُواْ نُرِيدُ أَن نَّأۡكُلَ مِنۡهَا وَتَطۡمَئِنَّ قُلُوبُنَا وَنَعۡلَمَ أَن قَدۡ صَدَقۡتَنَا وَنَكُونَ عَلَيۡهَا مِنَ ٱلشَّٰهِدِينَ","782":"قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلۡ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدٗا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةٗ مِّنكَۖ وَٱرۡزُقۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰزِقِينَ","783":"قَالَ ٱللَّهُ إِنِّي مُنَزِّلُهَا عَلَيۡكُمۡۖ فَمَن يَكۡفُرۡ بَعۡدُ مِنكُمۡ فَإِنِّيٓ أُعَذِّبُهُۥ عَذَابٗا لَّآ أُعَذِّبُهُۥٓ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ","887":"وَهُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ نَبَاتَ كُلِّ شَيۡءٖ فَأَخۡرَجۡنَا مِنۡهُ خَضِرٗا نُّخۡرِجُ مِنۡهُ حَبّٗا مُّتَرَاكِبٗا وَمِنَ ٱلنَّخۡلِ مِن طَلۡعِهَا قِنۡوَانٞ دَانِيَةٞ وَجَنَّٰتٖ مِّنۡ أَعۡنَابٖ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُشۡتَبِهٗا وَغَيۡرَ مُتَشَٰبِهٍۗ ٱنظُرُوٓاْ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَيَنۡعِهِۦٓۚ إِنَّ فِي ذَٰلِكُمۡ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ","906":"فَكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤۡمِنِينَ","907":"وَمَا لَكُمۡ أَلَّا تَأۡكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَقَدۡ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيۡكُمۡ إِلَّا مَا ٱضۡطُرِرۡتُمۡ إِلَيۡهِۗ وَإِنَّ كَثِيرٗا لَّيُضِلُّونَ بِأَهۡوَآئِهِم بِغَيۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِينَ","929":"۞ وَهُوَ ٱلَّذِيٓ أَنشَأَ جَنَّٰتٖ مَّعۡرُوشَٰتٖ وَغَيۡرَ مَعۡرُوشَٰتٖ وَٱلنَّخۡلَ وَٱلزَّرۡعَ مُخۡتَلِفًا أُكُلُهُۥ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهٗا وَغَيۡرَ مُتَشَٰبِهٖۚ كُلُواْ مِن ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَءَاتُواْ حَقَّهُۥ يَوۡمَ حَصَادِهِۦۖ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ","930":"وَمِنَ ٱلۡأَنۡعَٰمِ حَمُولَةٗ وَفَرۡشٗاۚ كُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ","984":"۞ يَٰبَنِيٓ ءَادَمَ خُذُواْ زِينَتَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ","985":"قُلۡ مَنۡ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِيٓ أَخۡرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزۡقِۚ قُلۡ هِيَ لِلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا خَالِصَةٗ يَوۡمَ ٱلۡقِيَٰمَةِۗ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ","1110":"ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِيَّ ٱلۡأُمِّيَّ ٱلَّذِي يَجِدُونَهُۥ مَكۡتُوبًا عِندَهُمۡ فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ يَأۡمُرُهُم بِٱلۡمَعۡرُوفِ وَيَنۡهَىٰهُمۡ عَنِ ٱلۡمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيۡهِمُ ٱلۡخَبَٰٓئِثَ وَيَضَعُ عَنۡهُمۡ إِصۡرَهُمۡ وَٱلۡأَغۡلَٰلَ ٱلَّتِي كَانَتۡ عَلَيۡهِمۡۚ فَٱلَّذِينَ ءَامَنُواْ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُواْ ٱلنُّورَ ٱلَّذِيٓ أُنزِلَ مَعَهُۥٓ أُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","1541":"وَلَقَدۡ جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞۖ فَمَا لَبِثَ أَن جَآءَ بِعِجۡلٍ حَنِيذٖ","1542":"فَلَمَّا رَءَآ أَيۡدِيَهُمۡ لَا تَصِلُ إِلَيۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۚ قَالُواْ لَا تَخَفۡ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمِ لُوطٖ","1631":"وَدَخَلَ مَعَهُ ٱلسِّجۡنَ فَتَيَانِۖ قَالَ أَحَدُهُمَآ إِنِّيٓ أَرَىٰنِيٓ أَعۡصِرُ خَمۡرٗاۖ وَقَالَ ٱلۡأٓخَرُ إِنِّيٓ أَرَىٰنِيٓ أَحۡمِلُ فَوۡقَ رَأۡسِي خُبۡزٗا تَأۡكُلُ ٱلطَّيۡرُ مِنۡهُۖ نَبِّئۡنَا بِتَأۡوِيلِهِۦٓۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِينَ","1642":"قَالَ تَزۡرَعُونَ سَبۡعَ سِنِينَ دَأَبٗا فَمَا حَصَدتُّمۡ فَذَرُوهُ فِي سُنۢبُلِهِۦٓ إِلَّا قَلِيلٗا مِّمَّا تَأۡكُلُونَ","1643":"ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ سَبۡعٞ شِدَادٞ يَأۡكُلۡنَ مَا قَدَّمۡتُمۡ لَهُنَّ إِلَّا قَلِيلٗا مِّمَّا تُحۡصِنُونَ","1644":"ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ عَامٞ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعۡصِرُونَ","1710":"وَفِي ٱلۡأَرۡضِ قِطَعٞ مُّتَجَٰوِرَٰتٞ وَجَنَّٰتٞ مِّنۡ أَعۡنَٰبٖ وَزَرۡعٞ وَنَخِيلٞ صِنۡوَانٞ وَغَيۡرُ صِنۡوَانٖ يُسۡقَىٰ بِمَآءٖ وَٰحِدٖ وَنُفَضِّلُ بَعۡضَهَا عَلَىٰ بَعۡضٖ فِي ٱلۡأُكُلِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ","1773":"أَلَمۡ تَرَ كَيۡفَ ضَرَبَ ٱللَّهُ مَثَلٗا كَلِمَةٗ طَيِّبَةٗ كَشَجَرَةٖ طَيِّبَةٍ أَصۡلُهَا ثَابِتٞ وَفَرۡعُهَا فِي ٱلسَّمَآءِ","1774":"تُؤۡتِيٓ أُكُلَهَا كُلَّ حِينِۭ بِإِذۡنِ رَبِّهَاۗ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ","1786":"رَّبَّنَآ إِنِّيٓ أَسۡكَنتُ مِن ذُرِّيَّتِي بِوَادٍ غَيۡرِ ذِي زَرۡعٍ عِندَ بَيۡتِكَ ٱلۡمُحَرَّمِ رَبَّنَا لِيُقِيمُواْ ٱلصَّلَوٰةَ فَٱجۡعَلۡ أَفۡـِٔدَةٗ مِّنَ ٱلنَّاسِ تَهۡوِيٓ إِلَيۡهِمۡ وَٱرۡزُقۡهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَشۡكُرُونَ","1911":"يُنۢبِتُ لَكُم بِهِ ٱلزَّرۡعَ وَٱلزَّيۡتُونَ وَٱلنَّخِيلَ وَٱلۡأَعۡنَٰبَ وَمِن كُلِّ ٱلثَّمَرَٰتِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ","1914":"وَهُوَ ٱلَّذِي سَخَّرَ ٱلۡبَحۡرَ لِتَأۡكُلُواْ مِنۡهُ لَحۡمٗا طَرِيّٗا وَتَسۡتَخۡرِجُواْ مِنۡهُ حِلۡيَةٗ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ مَوَاخِرَ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ","1966":"وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهِۦ مِنۢ بَيۡنِ فَرۡثٖ وَدَمٖ لَّبَنًا خَالِصٗا سَآئِغٗا لِّلشَّٰرِبِينَ","1967":"وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلۡأَعۡنَٰبِ تَتَّخِذُونَ مِنۡهُ سَكَرٗا وَرِزۡقًا حَسَنًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡقِلُونَ","1968":"وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ أَنِ ٱتَّخِذِي مِنَ ٱلۡجِبَالِ بُيُوتٗا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعۡرِشُونَ","1969":"ثُمَّ كُلِي مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسۡلُكِي سُبُلَ رَبِّكِ ذُلُلٗاۚ يَخۡرُجُ مِنۢ بُطُونِهَا شَرَابٞ مُّخۡتَلِفٌ أَلۡوَٰنُهُۥ فِيهِ شِفَآءٞ لِّلنَّاسِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ","2012":"وَضَرَبَ ٱللَّهُ مَثَلٗا قَرۡيَةٗ كَانَتۡ ءَامِنَةٗ مُّطۡمَئِنَّةٗ يَأۡتِيهَا رِزۡقُهَا رَغَدٗا مِّن كُلِّ مَكَانٖ فَكَفَرَتۡ بِأَنۡعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلۡجُوعِ وَٱلۡخَوۡفِ بِمَا كَانُواْ يَصۡنَعُونَ","2054":"وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَلَا تُبَذِّرۡ تَبۡذِيرًا","2055":"إِنَّ ٱلۡمُبَذِّرِينَ كَانُوٓاْ إِخۡوَٰنَ ٱلشَّيَٰطِينِۖ وَكَانَ ٱلشَّيۡطَٰنُ لِرَبِّهِۦ كَفُورٗا","2158":"وَكَذَٰلِكَ بَعَثۡنَٰهُمۡ لِيَتَسَآءَلُواْ بَيۡنَهُمۡۚ قَالَ قَآئِلٞ مِّنۡهُمۡ كَمۡ لَبِثۡتُمۡۖ قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۚ قَالُواْ رَبُّكُمۡ أَعۡلَمُ بِمَا لَبِثۡتُمۡ فَٱبۡعَثُوٓاْ أَحَدَكُم بِوَرِقِكُمۡ هَٰذِهِۦٓ إِلَى ٱلۡمَدِينَةِ فَلۡيَنظُرۡ أَيُّهَآ أَزۡكَىٰ طَعَامٗا فَلۡيَأۡتِكُم بِرِزۡقٖ مِّنۡهُ وَلۡيَتَلَطَّفۡ وَلَا يُشۡعِرَنَّ بِكُمۡ أَحَدًا","2201":"فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدۡ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبٗا","2202":"قَالَ أَرَءَيۡتَ إِذۡ أَوَيۡنَآ إِلَى ٱلصَّخۡرَةِ فَإِنِّي نَسِيتُ ٱلۡحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيۡطَٰنُ أَنۡ أَذۡكُرَهُۥۚ وَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ عَجَبٗا","2272":"فَأَجَآءَهَا ٱلۡمَخَاضُ إِلَىٰ جِذۡعِ ٱلنَّخۡلَةِ قَالَتۡ يَٰلَيۡتَنِي مِتُّ قَبۡلَ هَٰذَا وَكُنتُ نَسۡيٗا مَّنسِيّٗا","2273":"فَنَادَىٰهَا مِن تَحۡتِهَآ أَلَّا تَحۡزَنِي قَدۡ جَعَلَ رَبُّكِ تَحۡتَكِ سَرِيّٗا","2274":"وَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا","2275":"فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنٗاۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلۡبَشَرِ أَحَدٗا فَقُولِيٓ إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا فَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيّٗا","2428":"كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَلَا تَطۡغَوۡاْ فِيهِ فَيَحِلَّ عَلَيۡكُمۡ غَضَبِيۖ وَمَن يَحۡلِلۡ عَلَيۡهِ غَضَبِي فَقَدۡ هَوَىٰ","2512":"أَوَلَمۡ يَرَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقٗا فَفَتَقۡنَٰهُمَاۖ وَجَعَلۡنَا مِنَ ٱلۡمَآءِ كُلَّ شَيۡءٍ حَيٍّۚ أَفَلَا يُؤۡمِنُونَ","2622":"لِّيَشۡهَدُواْ مَنَٰفِعَ لَهُمۡ وَيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ فِيٓ أَيَّامٖ مَّعۡلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۖ فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡبَآئِسَ ٱلۡفَقِيرَ","2630":"وَٱلۡبُدۡنَ جَعَلۡنَٰهَا لَكُم مِّن شَعَٰٓئِرِ ٱللَّهِ لَكُمۡ فِيهَا خَيۡرٞۖ فَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهَا صَوَآفَّۖ فَإِذَا وَجَبَتۡ جُنُوبُهَا فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡقَانِعَ وَٱلۡمُعۡتَرَّۚ كَذَٰلِكَ سَخَّرۡنَٰهَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ","2691":"فَأَنشَأۡنَا لَكُم بِهِۦ جَنَّٰتٖ مِّن نَّخِيلٖ وَأَعۡنَٰبٖ لَّكُمۡ فِيهَا فَوَٰكِهُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ","2692":"وَشَجَرَةٗ تَخۡرُجُ مِن طُورِ سَيۡنَآءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغٖ لِّلۡأٓكِلِينَ","2825":"۞ ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ مَثَلُ نُورِهِۦ كَمِشۡكَوٰةٖ فِيهَا مِصۡبَاحٌۖ ٱلۡمِصۡبَاحُ فِي زُجَاجَةٍۖ ٱلزُّجَاجَةُ كَأَنَّهَا كَوۡكَبٞ دُرِّيّٞ يُوقَدُ مِن شَجَرَةٖ مُّبَٰرَكَةٖ زَيۡتُونَةٖ لَّا شَرۡقِيَّةٖ وَلَا غَرۡبِيَّةٖ يَكَادُ زَيۡتُهَا يُضِيٓءُ وَلَوۡ لَمۡ تَمۡسَسۡهُ نَارٞۚ نُّورٌ عَلَىٰ نُورٖۚ يَهۡدِي ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُۚ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَٰلَ لِلنَّاسِۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ","2851":"لَّيۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجٞ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجٞ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجٞ وَلَا عَلَىٰٓ أَنفُسِكُمۡ أَن تَأۡكُلُواْ مِنۢ بُيُوتِكُمۡ أَوۡ بُيُوتِ ءَابَآئِكُمۡ أَوۡ بُيُوتِ أُمَّهَٰتِكُمۡ أَوۡ بُيُوتِ إِخۡوَٰنِكُمۡ أَوۡ بُيُوتِ أَخَوَٰتِكُمۡ أَوۡ بُيُوتِ أَعۡمَٰمِكُمۡ أَوۡ بُيُوتِ عَمَّٰتِكُمۡ أَوۡ بُيُوتِ أَخۡوَٰلِكُمۡ أَوۡ بُيُوتِ خَٰلَٰتِكُمۡ أَوۡ مَا مَلَكۡتُم مَّفَاتِحَهُۥٓ أَوۡ صَدِيقِكُمۡۚ لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَأۡكُلُواْ جَمِيعًا أَوۡ أَشۡتَاتٗاۚ فَإِذَا دَخَلۡتُم بُيُوتٗا فَسَلِّمُواْ عَلَىٰٓ أَنفُسِكُمۡ تَحِيَّةٗ مِّنۡ عِندِ ٱللَّهِ مُبَٰرَكَةٗ طَيِّبَةٗۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ","2921":"وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا","3585":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتَ ٱلنَّبِيِّ إِلَّآ أَن يُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَيۡرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنۡ إِذَا دُعِيتُمۡ فَٱدۡخُلُواْ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُواْ وَلَا مُسۡتَـٔۡنِسِينَ لِحَدِيثٍۚ إِنَّ ذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ وَٱللَّهُ لَا يَسۡتَحۡيِۦ مِنَ ٱلۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعٗا فَسۡـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٖۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ وَمَا كَانَ لَكُمۡ أَن تُؤۡذُواْ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓاْ أَزۡوَٰجَهُۥ مِنۢ بَعۡدِهِۦٓ أَبَدًاۚ إِنَّ ذَٰلِكُمۡ كَانَ عِندَ ٱللَّهِ عَظِيمًا","3620":"لَقَدۡ كَانَ لِسَبَإٖ فِي مَسۡكَنِهِمۡ ءَايَةٞۖ جَنَّتَانِ عَن يَمِينٖ وَشِمَالٖۖ كُلُواْ مِن رِّزۡقِ رَبِّكُمۡ وَٱشۡكُرُواْ لَهُۥۚ بَلۡدَةٞ طَيِّبَةٞ وَرَبٌّ غَفُورٞ","3737":"وَءَايَةٞ لَّهُمُ ٱلۡأَرۡضُ ٱلۡمَيۡتَةُ أَحۡيَيۡنَٰهَا وَأَخۡرَجۡنَا مِنۡهَا حَبّٗا فَمِنۡهُ يَأۡكُلُونَ","3738":"وَجَعَلۡنَا فِيهَا جَنَّٰتٖ مِّن نَّخِيلٖ وَأَعۡنَٰبٖ وَفَجَّرۡنَا فِيهَا مِنَ ٱلۡعُيُونِ","3739":"لِيَأۡكُلُواْ مِن ثَمَرِهِۦ وَمَا عَمِلَتۡهُ أَيۡدِيهِمۡۚ أَفَلَا يَشۡكُرُونَ","3932":"۞ فَنَبَذۡنَٰهُ بِٱلۡعَرَآءِ وَهُوَ سَقِيمٞ","3933":"وَأَنۢبَتۡنَا عَلَيۡهِ شَجَرَةٗ مِّن يَقۡطِينٖ","4456":"إِنَّ شَجَرَتَ ٱلزَّقُّومِ","4457":"طَعَامُ ٱلۡأَثِيمِ","4458":"كَٱلۡمُهۡلِ يَغۡلِي فِي ٱلۡبُطُونِ","4459":"كَغَلۡيِ ٱلۡحَمِيمِ","4559":"مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۖ فِيهَآ أَنۡهَٰرٞ مِّن مَّآءٍ غَيۡرِ ءَاسِنٖ وَأَنۡهَٰرٞ مِّن لَّبَنٖ لَّمۡ يَتَغَيَّرۡ طَعۡمُهُۥ وَأَنۡهَٰرٞ مِّنۡ خَمۡرٖ لَّذَّةٖ لِّلشَّٰرِبِينَ وَأَنۡهَٰرٞ مِّنۡ عَسَلٖ مُّصَفّٗىۖ وَلَهُمۡ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغۡفِرَةٞ مِّن رَّبِّهِمۡۖ كَمَنۡ هُوَ خَٰلِدٞ فِي ٱلنَّارِ وَسُقُواْ مَآءً حَمِيمٗا فَقَطَّعَ أَمۡعَآءَهُمۡ","4638":"وَنَزَّلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ مُّبَٰرَكٗا فَأَنۢبَتۡنَا بِهِۦ جَنَّٰتٖ وَحَبَّ ٱلۡحَصِيدِ","4639":"وَٱلنَّخۡلَ بَاسِقَٰتٖ لَّهَا طَلۡعٞ نَّضِيدٞ","4640":"رِّزۡقٗا لِّلۡعِبَادِۖ وَأَحۡيَيۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ ٱلۡخُرُوجُ","4756":"وَأَمۡدَدۡنَٰهُم بِفَٰكِهَةٖ وَلَحۡمٖ مِّمَّا يَشۡتَهُونَ","4757":"يَتَنَٰزَعُونَ فِيهَا كَأۡسٗا لَّا لَغۡوٞ فِيهَا وَلَا تَأۡثِيمٞ","4910":"وَٱلۡأَرۡضَ وَضَعَهَا لِلۡأَنَامِ","4911":"فِيهَا فَٰكِهَةٞ وَٱلنَّخۡلُ ذَاتُ ٱلۡأَكۡمَامِ","4912":"وَٱلۡحَبُّ ذُو ٱلۡعَصۡفِ وَٱلرَّيۡحَانُ","4913":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","4968":"فِيهِمَا فَٰكِهَةٞ وَنَخۡلٞ وَرُمَّانٞ","4998":"وَفَٰكِهَةٖ مِّمَّا يَتَخَيَّرُونَ","4999":"وَلَحۡمِ طَيۡرٖ مِّمَّا يَشۡتَهُونَ","5005":"وَأَصۡحَٰبُ ٱلۡيَمِينِ مَآ أَصۡحَٰبُ ٱلۡيَمِينِ","5006":"فِي سِدۡرٖ مَّخۡضُودٖ","5007":"وَطَلۡحٖ مَّنضُودٖ","5008":"وَظِلّٖ مَّمۡدُودٖ","5009":"وَمَآءٖ مَّسۡكُوبٖ","5010":"وَفَٰكِهَةٖ كَثِيرَةٖ","5011":"لَّا مَقۡطُوعَةٖ وَلَا مَمۡنُوعَةٖ","5046":"أَفَرَءَيۡتُمُ ٱلۡمَآءَ ٱلَّذِي تَشۡرَبُونَ","5047":"ءَأَنتُمۡ أَنزَلۡتُمُوهُ مِنَ ٱلۡمُزۡنِ أَمۡ نَحۡنُ ٱلۡمُنزِلُونَ","5048":"لَوۡ نَشَآءُ جَعَلۡنَٰهُ أُجَاجٗا فَلَوۡلَا تَشۡكُرُونَ","5343":"فَهُوَ فِي عِيشَةٖ رَّاضِيَةٖ","5344":"فِي جَنَّةٍ عَالِيَةٖ","5345":"قُطُوفُهَا دَانِيَةٞ","5346":"كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَآ أَسۡلَفۡتُمۡ فِي ٱلۡأَيَّامِ ٱلۡخَالِيَةِ","5355":"إِنَّهُۥ كَانَ لَا يُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِيمِ","5356":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","5357":"فَلَيۡسَ لَهُ ٱلۡيَوۡمَ هَٰهُنَا حَمِيمٞ","5358":"وَلَا طَعَامٌ إِلَّا مِنۡ غِسۡلِينٖ","5359":"لَّا يَأۡكُلُهُۥٓ إِلَّا ٱلۡخَٰطِـُٔونَ","5598":"وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينٗا وَيَتِيمٗا وَأَسِيرًا","5599":"إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا","5781":"فَلۡيَنظُرِ ٱلۡإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ","5782":"أَنَّا صَبَبۡنَا ٱلۡمَآءَ صَبّٗا","5783":"ثُمَّ شَقَقۡنَا ٱلۡأَرۡضَ شَقّٗا","5784":"فَأَنۢبَتۡنَا فِيهَا حَبّٗا","5785":"وَعِنَبٗا وَقَضۡبٗا","5786":"وَزَيۡتُونٗا وَنَخۡلٗا","5787":"وَحَدَآئِقَ غُلۡبٗا","5972":"لَّيۡسَ لَهُمۡ طَعَامٌ إِلَّا مِن ضَرِيعٖ","5973":"لَّا يُسۡمِنُ وَلَا يُغۡنِي مِن جُوعٖ","6033":"فَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ","6034":"وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ","6035":"فَكُّ رَقَبَةٍ","6036":"أَوۡ إِطۡعَٰمٞ فِي يَوۡمٖ ذِي مَسۡغَبَةٖ","6037":"يَتِيمٗا ذَا مَقۡرَبَةٍ","6038":"أَوۡ مِسۡكِينٗا ذَا مَتۡرَبَةٖ","6098":"وَٱلتِّينِ وَٱلزَّيۡتُونِ","6099":"وَطُورِ سِينِينَ","6100":"وَهَٰذَا ٱلۡبَلَدِ ٱلۡأَمِينِ","6195":"فَلۡيَعۡبُدُواْ رَبَّ هَٰذَا ٱلۡبَيۡتِ","6196":"ٱلَّذِيٓ أَطۡعَمَهُم مِّن جُوعٖ وَءَامَنَهُم مِّنۡ خَوۡفِۭ","6197":"أَرَءَيۡتَ ٱلَّذِي يُكَذِّبُ بِٱلدِّينِ","6198":"فَذَٰلِكَ ٱلَّذِي يَدُعُّ ٱلۡيَتِيمَ","6199":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ"},"nay":126};
